// Package rapidmlx wraps the OpenAI-compatible HTTP surface exposed by
// Rapid-MLX (https://github.com/raullenchai/Rapid-MLX). It is a concrete
// provider type distinct from vLLM so the service layer can keep provider
// identity separate from utilization probing, which Rapid-MLX exposes on a
// different observability endpoint family.
package rapidmlx

import (
	agentcore "github.com/DocumentDrivenDX/fizeau/internal/core"
	"github.com/DocumentDrivenDX/fizeau/internal/provider/openai"
	"github.com/DocumentDrivenDX/fizeau/internal/provider/registry"
	"github.com/DocumentDrivenDX/fizeau/internal/reasoning"
)

const DefaultBaseURL = "http://localhost:8000/v1"

func init() {
	registry.Register(registry.Descriptor{
		Type: "rapid-mlx",
		Factory: func(in registry.Inputs) agentcore.Provider {
			return New(Config{
				BaseURL:      in.BaseURL,
				APIKey:       in.APIKey,
				Model:        in.Model,
				ModelPattern: in.ModelPattern,
				KnownModels:  in.KnownModels,
				Headers:      in.Headers,
				Reasoning:    in.Reasoning,
			})
		},
		DefaultBaseURL: DefaultBaseURL,
		DefaultPort:    8000,
	})
}

// ProtocolCapabilities keeps Rapid-MLX on the standard OpenAI-compatible
// surface. The provider remains distinct from vLLM at the type level.
var ProtocolCapabilities = openai.OpenAIProtocolCapabilities

type Config struct {
	BaseURL      string
	APIKey       string
	Model        string
	ModelPattern string
	KnownModels  map[string]string
	Headers      map[string]string
	Reasoning    reasoning.Reasoning
}

func New(cfg Config) *openai.Provider {
	baseURL := cfg.BaseURL
	if baseURL == "" {
		baseURL = DefaultBaseURL
	}
	return openai.New(openai.Config{
		BaseURL:        baseURL,
		APIKey:         cfg.APIKey,
		Model:          cfg.Model,
		ProviderName:   "rapid-mlx",
		ProviderSystem: "rapid-mlx",
		ModelPattern:   cfg.ModelPattern,
		KnownModels:    cfg.KnownModels,
		Headers:        cfg.Headers,
		Reasoning:      cfg.Reasoning,
		Capabilities:   &ProtocolCapabilities,
	})
}

package config

import (
	"path/filepath"
	"time"

	fizeau "github.com/DocumentDrivenDX/fizeau"
)

func init() {
	// Register the config loader into the root package so that fizeau.New can
	// load configuration without importing this package directly (which would
	// create an import cycle: config → agent → config).
	fizeau.RegisterConfigLoader(func(dir string) (fizeau.ServiceConfig, error) {
		cfg, err := Load(dir)
		if err != nil {
			return nil, err
		}
		return &configServiceConfig{cfg: cfg, baseDir: dir}, nil
	})
}

// configServiceConfig wraps a loaded *Config and satisfies fizeau.ServiceConfig.
// It is the agent-internal equivalent of DDx's ServiceConfigAdapter.
type configServiceConfig struct {
	cfg     *Config
	baseDir string
}

func NewServiceConfig(cfg *Config, baseDir string) fizeau.ServiceConfig {
	return &configServiceConfig{cfg: cfg, baseDir: baseDir}
}

func (c *configServiceConfig) ProviderNames() []string {
	if c.cfg == nil {
		return nil
	}
	return c.cfg.ProviderNames()
}

func (c *configServiceConfig) DefaultProviderName() string {
	if c.cfg == nil {
		return ""
	}
	return c.cfg.DefaultName()
}

func (c *configServiceConfig) Provider(name string) (fizeau.ServiceProviderEntry, bool) {
	if c.cfg == nil {
		return fizeau.ServiceProviderEntry{}, false
	}
	pc, ok := c.cfg.Providers[name]
	if !ok {
		return fizeau.ServiceProviderEntry{}, false
	}
	endpoints := make([]fizeau.ServiceProviderEndpoint, 0, len(pc.Endpoints))
	for _, endpoint := range pc.Endpoints {
		endpoints = append(endpoints, fizeau.ServiceProviderEndpoint{
			Name:    endpoint.Name,
			BaseURL: endpoint.BaseURL,
		})
	}
	return fizeau.ServiceProviderEntry{
		Type:             pc.Type,
		BaseURL:          pc.BaseURL,
		Endpoints:        endpoints,
		APIKey:           pc.APIKey,
		Model:            pc.Model,
		DailyTokenBudget: pc.DailyTokenBudget,
	}, true
}

func (c *configServiceConfig) HealthCooldown() time.Duration {
	if c.cfg == nil || c.cfg.Routing.HealthCooldown == "" {
		return 0
	}
	d, err := time.ParseDuration(c.cfg.Routing.HealthCooldown)
	if err != nil {
		return 0
	}
	return d
}

func (c *configServiceConfig) WorkDir() string {
	return c.baseDir
}

func (c *configServiceConfig) SessionLogDir() string {
	workDir := c.WorkDir()
	if workDir == "" {
		return ""
	}
	return filepath.Join(workDir, ProjectConfigDirName(), "sessions")
}

