	}

	snap, _ := claudeharness.ReadClaudeQuotaFrom(cachePath)
	if snap != nil && claudeharness.DecideClaudeQuotaRouting(snap, time.Now(), debounce).Fresh {
		// Cache is fresh enough; skip the expensive PTY probe.
		return
	}

