func liveListModelsEnsureV1BaseURL(raw string) string {
	raw = strings.TrimRight(strings.TrimSpace(raw), "/")
	parsed, err := url.Parse(raw)
	if err != nil || parsed.Path == "" || strings.HasSuffix(parsed.Path, "/v1") {
		return raw
	}
	return raw + "/v1"
}
